-- =============================================================================
-- Kairo Phase 4A Schema — PostgreSQL
-- Purpose:
--   1. Create MemoryIngestionJobs table with JobId BIGINT GENERATED BY DEFAULT AS IDENTITY.
--   2. Safe, automated, zero-loss migration for existing databases with UUID JobId.
--   3. Supporting indexes for atomic claiming, worker concurrency, and lookups.
--   4. Fully idempotent: safe to execute multiple times against fresh or existing databases.
--
-- Deployment Prerequisites:
--   • Drain active jobs: Ensure all Pending and Processing jobs reach completion,
--     failure, or cancellation prior to running migration.
--   • Confirm no external clients or systems hold unresolved dependencies on old
--     GUID job IDs (legacy GUID mapping is not retained).
-- =============================================================================

DO $$
BEGIN
    -- Case 1: Existing table with UUID JobId column — execute automated migration
    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_name = 'MemoryIngestionJobs'
          AND column_name = 'JobId'
          AND data_type = 'uuid'
    ) THEN
        RAISE NOTICE 'Migrating existing MemoryIngestionJobs table from UUID to BIGINT IDENTITY...';

        -- Step 1: Rename old table
        ALTER TABLE "MemoryIngestionJobs" RENAME TO "MemoryIngestionJobs_OldUuid";

        -- Step 2: Drop old indexes to avoid naming conflicts
        DROP INDEX IF EXISTS "IX_MemoryIngestionJobs_Claiming";
        DROP INDEX IF EXISTS "IX_MemoryIngestionJobs_User_Project";
        DROP INDEX IF EXISTS "IX_MemoryIngestionJobs_MemoryId";

        -- Step 3: Create new table with BIGINT GENERATED BY DEFAULT AS IDENTITY
        CREATE TABLE "MemoryIngestionJobs" (
            "JobId"         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            "ProjectId"     BIGINT NOT NULL,
            "UserId"        BIGINT NOT NULL,
            "ScopeId"       BIGINT NULL,
            "MemoryId"      BIGINT NULL,
            "JobType"       VARCHAR(50) NOT NULL,
            "Status"        VARCHAR(30) NOT NULL DEFAULT 'Pending',
            "Payload"       TEXT NULL,
            "Attempts"      INT NOT NULL DEFAULT 0,
            "MaxAttempts"   INT NOT NULL DEFAULT 3,
            "AvailableAt"   TIMESTAMPTZ NOT NULL,
            "LockedUntil"   TIMESTAMPTZ NULL,
            "LockOwner"     VARCHAR(128) NULL,
            "LastError"     VARCHAR(2048) NULL,
            "CreatedAt"     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            "CompletedAt"   TIMESTAMPTZ NULL,

            CONSTRAINT "FK_MemoryIngestionJobs_Projects"
                FOREIGN KEY ("ProjectId") REFERENCES "Projects"("ProjectId"),
            CONSTRAINT "FK_MemoryIngestionJobs_Users"
                FOREIGN KEY ("UserId") REFERENCES "Users"("UserId"),
            CONSTRAINT "FK_MemoryIngestionJobs_Memories"
                FOREIGN KEY ("MemoryId") REFERENCES "Memories"("MemoryId") ON DELETE SET NULL,
            CONSTRAINT "FK_MemoryIngestionJobs_MemoryScopes"
                FOREIGN KEY ("ScopeId") REFERENCES "MemoryScopes"("ScopeId") ON DELETE SET NULL
        );

        -- Step 4: Migrate ALL existing records preserving order and all data
        INSERT INTO "MemoryIngestionJobs" (
            "ProjectId", "UserId", "ScopeId", "MemoryId",
            "JobType", "Status", "Payload", "Attempts", "MaxAttempts",
            "AvailableAt", "LockedUntil", "LockOwner", "LastError",
            "CreatedAt", "CompletedAt"
        )
        SELECT
            "ProjectId", "UserId", "ScopeId", "MemoryId",
            "JobType", "Status", "Payload", "Attempts", "MaxAttempts",
            "AvailableAt", "LockedUntil", "LockOwner", "LastError",
            "CreatedAt", "CompletedAt"
        FROM "MemoryIngestionJobs_OldUuid"
        ORDER BY "CreatedAt" ASC;

        -- Step 5: Create indexes
        CREATE INDEX "IX_MemoryIngestionJobs_Claiming"
            ON "MemoryIngestionJobs" ("Status", "AvailableAt", "LockedUntil");
        CREATE INDEX "IX_MemoryIngestionJobs_User_Project"
            ON "MemoryIngestionJobs" ("UserId", "ProjectId");
        CREATE INDEX "IX_MemoryIngestionJobs_MemoryId"
            ON "MemoryIngestionJobs" ("MemoryId");

        -- Step 6: Drop legacy table
        DROP TABLE "MemoryIngestionJobs_OldUuid";

        RAISE NOTICE 'Migration from UUID to BIGINT IDENTITY completed successfully.';

    -- Case 2: Fresh database — table does not exist
    ELSIF NOT EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_name = 'MemoryIngestionJobs'
    ) THEN
        RAISE NOTICE 'Creating fresh MemoryIngestionJobs table with BIGINT IDENTITY...';

        CREATE TABLE "MemoryIngestionJobs" (
            "JobId"         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            "ProjectId"     BIGINT NOT NULL,
            "UserId"        BIGINT NOT NULL,
            "ScopeId"       BIGINT NULL,
            "MemoryId"      BIGINT NULL,
            "JobType"       VARCHAR(50) NOT NULL,
            "Status"        VARCHAR(30) NOT NULL DEFAULT 'Pending',
            "Payload"       TEXT NULL,
            "Attempts"      INT NOT NULL DEFAULT 0,
            "MaxAttempts"   INT NOT NULL DEFAULT 3,
            "AvailableAt"   TIMESTAMPTZ NOT NULL,
            "LockedUntil"   TIMESTAMPTZ NULL,
            "LockOwner"     VARCHAR(128) NULL,
            "LastError"     VARCHAR(2048) NULL,
            "CreatedAt"     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            "CompletedAt"   TIMESTAMPTZ NULL,

            CONSTRAINT "FK_MemoryIngestionJobs_Projects"
                FOREIGN KEY ("ProjectId") REFERENCES "Projects"("ProjectId"),
            CONSTRAINT "FK_MemoryIngestionJobs_Users"
                FOREIGN KEY ("UserId") REFERENCES "Users"("UserId"),
            CONSTRAINT "FK_MemoryIngestionJobs_Memories"
                FOREIGN KEY ("MemoryId") REFERENCES "Memories"("MemoryId") ON DELETE SET NULL,
            CONSTRAINT "FK_MemoryIngestionJobs_MemoryScopes"
                FOREIGN KEY ("ScopeId") REFERENCES "MemoryScopes"("ScopeId") ON DELETE SET NULL
        );

        CREATE INDEX "IX_MemoryIngestionJobs_Claiming"
            ON "MemoryIngestionJobs" ("Status", "AvailableAt", "LockedUntil");
        CREATE INDEX "IX_MemoryIngestionJobs_User_Project"
            ON "MemoryIngestionJobs" ("UserId", "ProjectId");
        CREATE INDEX "IX_MemoryIngestionJobs_MemoryId"
            ON "MemoryIngestionJobs" ("MemoryId");

        RAISE NOTICE 'Fresh MemoryIngestionJobs table created successfully.';

    -- Case 3: Table already exists with BIGINT — idempotent no-op
    ELSE
        RAISE NOTICE 'MemoryIngestionJobs table already exists with BIGINT IDENTITY. No migration needed.';
    END IF;
END $$;

-- Section C: Schema Validation
SELECT
    column_name,
    data_type,
    column_default,
    is_nullable,
    identity_generation
FROM information_schema.columns
WHERE table_name = 'MemoryIngestionJobs'
ORDER BY ordinal_position;
